using System;
using System.IO;
using System.Linq;
using RingTimer;
class CycleTests {
 static int count;static void Check(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS "+name);count++;}
 static bool Near(double a,double b){return Math.Abs(a-b)<.01;}
 static int Main(string[] args){try{
  DateTime now=new DateTime(2026,11,1,15,59,50,DateTimeKind.Utc);var t=new TimerEngine(new TimerState(),()=>now);var zone=TimeZoneInfo.CreateCustomTimeZone("Eight",TimeSpan.FromHours(8),"Eight","Eight");var s=new StatsStore(null,zone);
  t.StartCycle(20,5,1);Check(t.State.Phase=="work"&&t.State.GroupIndex==1,"cycle starts with work");now=now.AddSeconds(12);s.UpdateLive(t.CurrentSession());Check(Near(s.Day(new DateTime(2026,11,1)).WorkSeconds,10)&&Near(s.Day(new DateTime(2026,11,2)).WorkSeconds,2),"live work splits at local midnight");
  now=now.AddSeconds(10);Check(t.Tick()&&t.State.Phase=="rest"&&Near(t.Remaining,3),"work automatically enters rest at exact deadline");s.Collect(t.State);s.UpdateLive(t.CurrentSession());Check(Near(s.Day(new DateTime(2026,11,2)).WorkSeconds,10)&&Near(s.Day(new DateTime(2026,11,2)).RestSeconds,2),"work and live rest are distinct");
  now=now.AddSeconds(3);Check(t.Tick()&&t.State.Status=="finished","one group stops after rest");s.Collect(t.State);s.UpdateLive(t.CurrentSession());now=now.AddHours(3);Check(!t.Tick()&&s.Records.Count==2,"waiting does not invent another group");
  t.StartCycle(10,3,3);now=now.AddSeconds(1000);Check(t.Tick()&&t.State.GroupIndex==3&&t.State.Status=="finished"&&t.State.PendingStats.Count==6,"catch-up respects group limit");Check(Near(t.State.PendingStats.Sum(r=>r.Spans.Sum(x=>(x.EndUtc-x.StartUtc)/(double)TimeSpan.TicksPerSecond)),39),"catch-up records exact work and rest durations");
  t.State.PendingStats.Clear();t.StartCycle(10,5,2);now=now.AddSeconds(4);t.Pause();now=now.AddHours(1);Check(Near(t.Remaining,6),"cycle pause freezes remaining time");t.Resume();now=now.AddSeconds(6);t.Tick();Check(t.State.Phase=="rest"&&Near(t.Remaining,5),"resume excludes pause from work");now=now.AddSeconds(2);t.StopCycle();Check(t.State.Status=="idle"&&t.State.PendingStats.Count==2&&t.State.PendingStats.Last().Kind=="rest"&&!t.State.PendingStats.Last().Complete,"manual stop retains elapsed partial rest");
  string dir=args[0];Directory.CreateDirectory(dir);string file=Path.Combine(dir,"cycle-state.json");t.State.PendingStats.Clear();t.StartCycle(5,2,2);t.State.Sound=false;t.Save(file);now=now.AddSeconds(8);var reload=new TimerEngine(TimerEngine.Load(file),()=>now);reload.Tick();Check(reload.State.Phase=="work"&&reload.State.GroupIndex==2&&Near(reload.Remaining,4)&&!reload.State.Sound,"restart restores cycle and catches up");
  var legacy=new TimerEngine(new TimerState{Status="running",Total=30,Remaining=30,Deadline=now.AddSeconds(20).Ticks},()=>now);long deadline=legacy.State.Deadline;Check(!legacy.State.Cycle&&legacy.State.Phase=="work"&&legacy.State.Deadline==deadline,"legacy timer retains its deadline and category");now=now.AddSeconds(21);legacy.Tick();Check(legacy.State.Status=="finished"&&legacy.State.PendingStats.Single().Kind=="work","legacy timer finishes once without starting rest");
  string oldPath=Path.Combine(dir,"history-"+Guid.NewGuid()+".json");var original=new StatsStore(oldPath,zone);original.Collect(legacy.State);string originalJson=File.ReadAllText(oldPath);string legacyJson=originalJson.Replace("\"Kind\":\"work\",","");File.WriteAllText(oldPath,legacyJson);var migrated=new StatsStore(oldPath,zone);var before=migrated.Aggregate(new DateTime(2026,1,1),new DateTime(2027,1,1));Check(Near(before.WorkSeconds,30)&&before.RestSeconds==0,"old history is counted as work");Check(File.ReadAllText(oldPath)==legacyJson,"loading old history does not rewrite it");
  t=new TimerEngine(new TimerState(),()=>now);t.StartCycle(2,1,1);now=now.AddSeconds(3);t.Tick();var replay=t.State.PendingStats.ToArray();migrated.Collect(t.State);foreach(var r in replay)t.State.PendingStats.Add(r);migrated.Collect(t.State);var after=new StatsStore(oldPath,zone).Aggregate(new DateTime(2026,1,1),new DateTime(2027,1,1));Check(Near(after.WorkSeconds,32)&&Near(after.RestSeconds,1)&&after.Sessions==3,"migration and replay preserve history and classified totals");
  bool rejected=false;try{t.StartCycle(10,5,0);}catch(ArgumentOutOfRangeException){rejected=true;}Check(rejected,"invalid group count rejected");t.StartCycle(1,1,99);now=now.AddSeconds(1000);t.Tick();Check(t.State.GroupIndex==99&&t.State.PendingStats.Count==198,"maximum groups remain bounded");
  string oldState=Path.Combine(dir,"old-state.json");File.WriteAllText(oldState,"{\"Status\":\"paused\",\"Total\":2700,\"Remaining\":1234,\"Sound\":false}");var preference=new TimerEngine(TimerEngine.Load(oldState),()=>now);Check(preference.State.WorkSeconds==2700&&preference.Remaining==1234&&!preference.State.Sound&&!preference.State.Cycle,"legacy configured duration and paused state preserved");preference.State.WorkSeconds=1200;preference.Save(oldState);Check(TimerEngine.Load(oldState).WorkSeconds==1200,"explicit new work preference wins over legacy total");
  Console.WriteLine(count+" cycle checks passed");return 0;
 }catch(Exception ex){Console.WriteLine("FAIL "+ex);return 1;}}
}
